from finquint.backtesting import MarketOrder
from finquint.strategies.base import Param, StrategyTemplate


class ChannelBreakoutStrategy:
    def __init__(self, symbol, lookback=20, units=5000, long_only=False):
        self.symbol = symbol
        self.lookback = int(lookback)
        self.units = units
        self.long_only = bool(long_only)

    def on_bar(self, context):
        history = context.history
        if history is None or len(history) == 0:
            return ()
        rows = history[history["symbol"] == self.symbol]
        closes = rows.sort_values("timestamp", kind="mergesort")["close"].dropna()
        n = self.lookback
        if len(closes) < n + 1:
            return ()
        window = closes.iloc[-(n + 1):-1]
        upper = float(window.max())
        lower = float(window.min())
        last = float(closes.iloc[-1])
        current = context.positions.get(self.symbol, 0)
        if last > upper:
            target = self.units
        elif last < lower:
            if self.long_only:
                target = 0
            else:
                target = -self.units
        else:
            return ()
        change = target - current
        if change == 0:
            return ()
        order_id = "channel_breakout-" + str(self.symbol) + "-" + str(context.timestamp)
        return (MarketOrder(order_id, self.symbol, change, context.timestamp),)


TEMPLATE = StrategyTemplate(
    "channel_breakout",
    "Channel breakout on one symbol: target +units when the close rises above the highest close of the previous `lookback` bars, and -units (or flat when long_only) when it falls below the lowest close of the previous `lookback` bars; otherwise keep the current position.",
    {
        "lookback": Param("integer", 2, 250, 20),
        "units": Param("number", 1, 10000, 5000),
        "long_only": Param("boolean", default=False),
    },
    ChannelBreakoutStrategy,
)

import math

import numpy
import pandas

from finquint.backtesting import MarketOrder
from finquint.strategies.base import Param, StrategyTemplate


class MeanReversionStrategy:
    def __init__(self, symbol, lookback=20, entry_z=2.0, units=5000, long_only=False):
        self.symbol = symbol
        self.lookback = int(lookback)
        self.entry_z = float(entry_z)
        self.units = float(units)
        self.long_only = bool(long_only)

    def _closes(self, history):
        if history is None or len(history) == 0:
            return None
        rows = history.loc[history["symbol"] == self.symbol]
        if len(rows) == 0:
            return None
        rows = rows.sort_values("timestamp", kind="mergesort")
        closes = pandas.to_numeric(rows["close"], errors="coerce").dropna()
        return closes

    def on_bar(self, context):
        closes = self._closes(context.history)
        if closes is None or len(closes) < self.lookback or self.lookback < 2:
            return ()
        window = numpy.asarray(closes.iloc[-self.lookback:], dtype=float)
        mean = float(numpy.mean(window))
        std = float(numpy.std(window, ddof=1))
        last = float(window[-1])
        if not (math.isfinite(mean) and math.isfinite(std) and math.isfinite(last)):
            return ()
        if std <= 0.0:
            return ()
        z = (last - mean) / std
        positions = context.positions if context.positions is not None else {}
        current = float(positions.get(self.symbol, 0.0))
        target = current
        if z <= -self.entry_z:
            target = self.units
        elif z >= self.entry_z:
            target = 0.0 if self.long_only else -self.units
        elif current > 0.0 and z >= 0.0:
            target = 0.0
        elif current < 0.0 and z <= 0.0:
            target = 0.0
        delta = target - current
        if abs(delta) < 1e-9:
            return ()
        order_id = "mr-" + str(self.symbol) + "-" + str(context.timestamp)
        return (MarketOrder(order_id, self.symbol, delta, context.timestamp),)


TEMPLATE = StrategyTemplate(
    "mean_reversion",
    "Mean reversion on one symbol: compute the z-score of the latest close against the rolling mean and sample standard deviation of the last `lookback` closes; go long `units` when z <= -entry_z, short `units` (or flat when long_only) when z >= entry_z, and close any open position once the close crosses back through its rolling mean.",
    {
        "lookback": Param("integer", 5, 250, 20),
        "entry_z": Param("number", 0.5, 5.0, 2.0),
        "units": Param("number", 1, 10000, 5000),
        "long_only": Param("boolean", default=False),
    },
    MeanReversionStrategy,
)

import math

import numpy

from finquint.backtesting import MarketOrder
from finquint.strategies.base import Param, StrategyTemplate

ANNUALIZATION = 252.0


class VolTargetTrend:
    def __init__(self, symbol, lookback=60, vol_window=20, target_vol=0.1, max_leverage=2.0, long_only=False):
        self.symbol = symbol
        self.lookback = int(lookback)
        self.vol_window = int(vol_window)
        self.target_vol = float(target_vol)
        self.max_leverage = float(max_leverage)
        self.long_only = bool(long_only)

    def on_bar(self, context):
        history = context.history
        if history is None or len(history) == 0:
            return ()
        rows = history[history["symbol"] == self.symbol]
        closes = rows["close"].astype(float).to_numpy()
        needed = max(self.lookback, self.vol_window) + 1
        if len(closes) < needed:
            return ()
        price = float(closes[-1])
        past = float(closes[-1 - self.lookback])
        if not (math.isfinite(price) and math.isfinite(past)):
            return ()
        if price <= 0 or past <= 0:
            return ()
        trend = price / past - 1.0
        direction = 0
        if trend > 0:
            direction = 1
        elif trend < 0:
            direction = -1
        if direction < 0 and self.long_only:
            direction = 0
        window = closes[-(self.vol_window + 1):]
        if not bool(numpy.all(numpy.isfinite(window))):
            return ()
        if bool(numpy.any(window <= 0)):
            return ()
        rets = numpy.diff(numpy.log(window))
        daily_vol = float(numpy.std(rets, ddof=1))
        if not math.isfinite(daily_vol):
            return ()
        annual_vol = daily_vol * math.sqrt(ANNUALIZATION)
        if annual_vol > 0:
            leverage = min(self.target_vol / annual_vol, self.max_leverage)
        else:
            leverage = self.max_leverage
        equity = float(context.equity)
        if not math.isfinite(equity) or equity <= 0:
            target = 0
        else:
            target = direction * math.floor(leverage * equity / price)
        current = context.positions.get(self.symbol, 0)
        if current is None:
            current = 0
        delta = target - current
        if delta == 0:
            return ()
        order_id = f"{self.symbol}-{context.timestamp}"
        return (MarketOrder(order_id, self.symbol, delta, context.timestamp),)


TEMPLATE = StrategyTemplate(
    "vol_target_trend",
    "Volatility-targeted trend on one symbol: direction is the sign of the return over the last `lookback` bars; size is equity times target_vol over annualized realized volatility of the last `vol_window` returns, capped at max_leverage, in whole units at the latest close. Flat instead of short when long_only.",
    {
        "lookback": Param("integer", 5, 250, 60),
        "vol_window": Param("integer", 5, 250, 20),
        "target_vol": Param("number", 0.01, 1.0, 0.1),
        "max_leverage": Param("number", 0.1, 5.0, 2.0),
        "long_only": Param("boolean", default=False),
    },
    VolTargetTrend,
)
